ps.pstext:
let p:integer = UInt(CRm[0] :: op2[2:0]);

if !(IsFeatureImplemented(FEAT_S1POE2) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif HaveEL(EL3) && PSTATE.EL == EL2 && EL3SDDUndefPriority() && SCR_EL3().POE2En == '0' then
    Undefined();
elsif EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EffectiveHCR_EL2_NVx() IN {'xx1'} then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        Undefined();
    end;
elsif PSTATE.EL == EL2 then
    if HaveEL(EL3) && SCR_EL3().POE2En == '0' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    else
        X{64}(t) = FGDTP_EL2((p * 2) + 1) :: FGDTP_EL2(p * 2);
    end;
elsif PSTATE.EL == EL3 then
    if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.E0 == '1' then
        AArch64_SystemAccessTrap(EL3, 0x18);
    else
        X{64}(t) = FGDTP_EL2((p * 2) + 1) :: FGDTP_EL2(p * 2);
    end;
end;

let p:integer = UInt(CRm[0] :: op2[2:0]);

if !(IsFeatureImplemented(FEAT_S1POE2) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif HaveEL(EL3) && PSTATE.EL == EL2 && EL3SDDUndefPriority() && SCR_EL3().POE2En == '0' then
    Undefined();
elsif EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EffectiveHCR_EL2_NVx() IN {'xx1'} then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        Undefined();
    end;
elsif PSTATE.EL == EL2 then
    if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.nTT == '1' then
        AArch64_FGDTSystemAccessTrap(EL2, 0x18);
    elsif HaveEL(EL3) && SCR_EL3().POE2En == '0' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    else
        FGDTP_EL2((p * 2) + 1, p * 2) = X{64}(t);
    end;
elsif PSTATE.EL == EL3 then
    if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.E0 == '1' then
        AArch64_SystemAccessTrap(EL3, 0x18);
    else
        FGDTP_EL2((p * 2) + 1, p * 2) = X{64}(t);
    end;
end;

let p:integer = UInt(CRm[0] :: op2[2:0]);

if !(IsFeatureImplemented(FEAT_S1POE2) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif HaveEL(EL3) && !(EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() || PSTATE.EL == EL3) && EL3SDDUndefPriority() && SCR_EL3().POE2En == '0' then
    Undefined();
elsif EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && (!IsHCRXEL2Enabled() || HCRX_EL2().POE2En == '0') then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_FGT2) && ((HaveEL(EL3) && SCR_EL3().FGTEn2 == '0') || HFGRTR2_EL2().nFGDTn_EL1 != '11') then
        if p >= 8 && HFGRTR2_EL2().nFGDTn_EL1 == '10' then
            AArch64_SystemAccessTrap(EL2, 0x18);
        elsif p >= 4 && HFGRTR2_EL2().nFGDTn_EL1 == '01' then
            AArch64_SystemAccessTrap(EL2, 0x18);
        else
            AArch64_SystemAccessTrap(EL2, 0x18);
        end;
    elsif HaveEL(EL3) && SCR_EL3().POE2En == '0' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    elsif EffectiveHCR_EL2_NVx() IN {'111'} then
        X{64}(t) = NVMem(0x600 + (8 * p));
    else
        X{64}(t) = FGDTP_EL1((p * 2) + 1) :: FGDTP_EL1(p * 2);
    end;
elsif PSTATE.EL == EL2 then
    if HaveEL(EL3) && SCR_EL3().POE2En == '0' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    elsif ELIsInHost(EL2) then
        X{64}(t) = FGDTP_EL2((p * 2) + 1) :: FGDTP_EL2(p * 2);
    else
        X{64}(t) = FGDTP_EL1((p * 2) + 1) :: FGDTP_EL1(p * 2);
    end;
elsif PSTATE.EL == EL3 then
    if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.E0 == '1' then
        AArch64_SystemAccessTrap(EL3, 0x18);
    else
        X{64}(t) = FGDTP_EL1((p * 2) + 1) :: FGDTP_EL1(p * 2);
    end;
end;

let p:integer = UInt(CRm[0] :: op2[2:0]);

if !(IsFeatureImplemented(FEAT_S1POE2) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif HaveEL(EL3) && !(EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() || PSTATE.EL == EL3) && EL3SDDUndefPriority() && SCR_EL3().POE2En == '0' then
    Undefined();
elsif EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() then
    Undefined();
elsif PSTATE.EL == EL1 then
    if IsFeatureImplemented(FEAT_S1POE2) && EffectiveHCR_EL2_NVx() IN {'x11'} && FGDTState.nH == '1' then
        AArch64_FGDTSystemAccessTrap(EL1, 0x18);
    elsif IsFeatureImplemented(FEAT_S1POE2) && FGDTState.nTT == '1' then
        AArch64_FGDTSystemAccessTrap(EL1, 0x18);
    elsif EL2Enabled() && (!IsHCRXEL2Enabled() || HCRX_EL2().POE2En == '0') then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_FGT2) && ((HaveEL(EL3) && SCR_EL3().FGTEn2 == '0') || HFGWTR2_EL2().nFGDTn_EL1 != '11') then
        if p >= 8 && HFGWTR2_EL2().nFGDTn_EL1 == '10' then
            AArch64_SystemAccessTrap(EL2, 0x18);
        elsif p >= 4 && HFGWTR2_EL2().nFGDTn_EL1 == '01' then
            AArch64_SystemAccessTrap(EL2, 0x18);
        else
            AArch64_SystemAccessTrap(EL2, 0x18);
        end;
    elsif HaveEL(EL3) && SCR_EL3().POE2En == '0' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    elsif EffectiveHCR_EL2_NVx() IN {'111'} then
        NVMem(0x600 + (8 * p)) = X{64}(t);
    else
        FGDTP_EL1((p * 2) + 1, p * 2) = X{64}(t);
    end;
elsif PSTATE.EL == EL2 then
    if HaveEL(EL3) && SCR_EL3().POE2En == '0' then
        if EL3SDDUndef() then
            Undefined();
        else
            AArch64_SystemAccessTrap(EL3, 0x18);
        end;
    elsif ELIsInHost(EL2) then
        if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.nTT == '1' then
            AArch64_FGDTSystemAccessTrap(EL2, 0x18);
        else
            FGDTP_EL2((p * 2) + 1, p * 2) = X{64}(t);
        end;
    else
        FGDTP_EL1((p * 2) + 1, p * 2) = X{64}(t);
    end;
elsif PSTATE.EL == EL3 then
    if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.E0 == '1' then
        AArch64_SystemAccessTrap(EL3, 0x18);
    else
        FGDTP_EL1((p * 2) + 1, p * 2) = X{64}(t);
    end;
end;
